record Product(long id, String name) {}
static Product mapRow(ResultSet rs) throws SQLException { return new Product(rs.getLong("id"), rs.getString("name")); }
static Product findById(Connection conn, long id) throws SQLException {
  try (PreparedStatement ps = conn.prepareStatement("SELECT * FROM products WHERE id=?")) {
    ps.setLong(1, id);
    try (ResultSet rs = ps.executeQuery()) { rs.next(); return mapRow(rs); }
  }
}

