static BigDecimal getRequiredBigDecimal(ResultSet rs, String column) throws SQLException {
  BigDecimal value = rs.getBigDecimal(column);
  if (value == null) throw new IllegalStateException("Nieoczekiwany NULL w kolumnie " + column);
  return value;
}
static Product mapRow(ResultSet rs) throws SQLException {
