static <T> List<T> findPage(Connection conn, String baseSql, int limit, int offset, ResultSetMapper<T> mapper) throws SQLException {
  List<T> result = new ArrayList<>();
  try (PreparedStatement ps = conn.prepareStatement(baseSql + " LIMIT ? OFFSET ?")) {
    ps.setInt(1, limit); ps.setInt(2, offset);
    try (ResultSet rs = ps.executeQuery()) { while (rs.next()) result.add(mapper.map(rs)); }
  }
  return result;
}
