class CachedProductRepository {
  private final Connection conn;
  private final Map<Long, Product> cache = new HashMap<>();
  CachedProductRepository(Connection conn) { this.conn = conn; }
  Product findById(long id) throws SQLException {
    if (cache.containsKey(id)) return cache.get(id);
    Product p = _Lesson17_ResultSetMapping.findById(conn, id);
    cache.put(id, p);
    return p;
  }
}

